public Optional<Tradable> getTradableById(String id){
  if (closedTradables == null) {
    return Optional.empty();
  }
  try {
    return closedTradables.stream().filter(e -> e != null && e.getId().equals(id)).findFirst();
  } catch (NullPointerException e) {
    return Optional.empty();
  }
}
